#!/usr/bin/env bash
# A proto field that reaches no surface is a field that was added for nothing.
#
# `apps/core/lib/stacks/gen/proto_json.ex` is GENERATED by `mix proto.sync`, so
# `Gen.<message>/1` always emits exactly the contract's fields. The
# hand-written serializers in `apps/core/lib/stacks_web/proto_json.ex` then
# narrow those maps with `Map.take`, and that narrowing is deliberate: a search
# hit does not need a description, a slim placement ref does not need reading
# progress.
#
# ⚠️ WHAT NOTHING CHECKED. Add a field to a proto message and the generated
# side carries it automatically — and every hand-written serializer silently
# drops it. `mix proto.sync --check` compares GENERATED files against what it
# would generate, so it cannot see a hand-written allowlist at all. The field
# exists in the contract, is emitted by codegen, reaches no client, and no test
# anywhere fails. That is this repository's dominant defect class — built but
# not wired — on the one path where the contract itself promises otherwise.
#
# WHY A BASELINE AND NOT A REASON PER FIELD. There are 98 (field, serializer)
# omissions today and almost all are legitimate narrowing. Demanding a written
# reason for each would produce 98 shallow reasons, which is worse than none
# because it reads as considered when it was not — and it is the same cry-wolf
# shape this project already rejected once, when an 18-name secrets denylist
# named eighteen non-defects.
#
# So the population is pinned instead. The baseline below is a statement of
# WHERE WE ARE, reviewable in a diff when it moves — not a blessing. The gate
# fails when the set GROWS, naming the new pair, which turns the next proto
# field addition into a decision; and it fails when the baseline holds an entry
# that no longer exists, so it cannot rot into a list nobody maintains.
set -uo pipefail

REPO_ROOT="$(git rev-parse --show-toplevel 2>/dev/null || echo .)"
cd "$REPO_ROOT" || exit 1

python3 - <<'PY'
import collections
import pathlib
import re
import sys

GEN_PATH = "apps/core/lib/stacks/gen/proto_json.ex"
HAND_PATH = "apps/core/lib/stacks_web/proto_json.ex"

# The omission set as it stands. Each entry is "serializer:field".
#
# To change it: run this gate, read what it names, and either carry the field
# in the serializer or add the pair here in the same commit. The diff is the
# record of that decision.
BASELINE = {
    "author:created_at",
    "author:open_library_id",
    "author:rss_feed_url",
    "author:updated_at",
    "blog_association:book_id",
    "blog_association:confidence",
    "blog_association:id",
    "blog_association:source",
    "blog_association:visible",
    "blog_post:visibility_group_id",
    "book:author_id",
    "book:created_at",
    "book:updated_at",
    "book_placement:book_edition_id",
    "book_placement:bookshelf_id",
    "book_placement:created_at",
    "book_placement:current_page",
    "book_placement:finished_at",
    "book_placement:formats",
    "book_placement:listing_min_price_cents",
    "book_placement:listing_mode",
    "book_placement:listing_price_cents",
    "book_placement:listing_status",
    "book_placement:placed_at",
    "book_placement:position",
    "book_placement:reading_status",
    "book_placement:removed_at",
    "book_placement:shelf_id",
    "book_placement:source",
    "book_placement:started_at",
    "book_placement:updated_at",
    "book_placement:visibility",
    "bookshelf_book:author_id",
    "bookshelf_book:bisac_codes",
    "bookshelf_book:created_at",
    "bookshelf_book:language",
    "bookshelf_book:subjects",
    "bookshelf_book:updated_at",
    "catalogue_book:author_id",
    "catalogue_book:bisac_codes",
    "catalogue_book:created_at",
    "catalogue_book:description",
    "catalogue_book:language",
    "catalogue_book:updated_at",
    "edition:created_at",
    "edition:google_books_id",
    "edition:open_library_id",
    "edition:updated_at",
    "listing:book_id",
    "placement_detail:book_edition_id",
    "placement_detail:book_id",
    "placement_detail:bookshelf_id",
    "placement_detail:created_at",
    "placement_detail:listing_min_price_cents",
    "placement_detail:listing_mode",
    "placement_detail:listing_price_cents",
    "placement_detail:listing_status",
    "placement_detail:removed_at",
    "placement_detail:shelf_id",
    "placement_detail:source",
    "placement_detail:updated_at",
    "placement_ref:book_edition_id",
    "placement_ref:created_at",
    "placement_ref:current_page",
    "placement_ref:finished_at",
    "placement_ref:formats",
    "placement_ref:listing_min_price_cents",
    "placement_ref:listing_mode",
    "placement_ref:listing_price_cents",
    "placement_ref:listing_status",
    "placement_ref:notes",
    "placement_ref:personal_rating",
    "placement_ref:reading_status",
    "placement_ref:source",
    "placement_ref:started_at",
    "placement_ref:updated_at",
    "placement_ref:visibility",
    "search_book:author_id",
    "search_book:bisac_codes",
    "search_book:created_at",
    "search_book:description",
    "search_book:language",
    "search_book:subjects",
    "search_book:updated_at",
    "user:age_verification_provider",
    "user:age_verified_at",
    "user:consent_analytics_at",
    "user:consent_writing_assistant",
    "user:consent_writing_assistant_at",
    "user:created_at",
    "user:email_confirmed",
    "user:notify_event_matches",
    "user:notify_group_invitations",
    "user:notify_marketplace",
    "user:notify_wishlist_availability",
    "user:onboarding_steps",
    "user:syndication_default",
    "user:updated_at",
}


def read(path):
    try:
        return pathlib.Path(path).read_text(encoding="utf-8")
    except OSError as exc:
        print(f"FAIL: cannot read {path}: {exc}", file=sys.stderr)
        print(
            "This gate compares GENERATED serializers against hand-written ones. The generated\n"
            "half is produced by `mix proto.sync`, so on a fresh clone run that first — this is a\n"
            "refusal, not a pass.",
            file=sys.stderr,
        )
        raise SystemExit(1)


gen_src = read(GEN_PATH)
hand_src = read(HAND_PATH)

# Module-attribute field lists, resolved so a serializer using `@user_auth_fields`
# is not reported as omitting everything in it. Without this the `user`
# serializer alone showed 29 phantom omissions instead of its real 14.
attrs = {}
for match in re.finditer(r"@([a-z_]+)\s+\[([^\]]*)\]", hand_src, re.S):
    attrs[match.group(1)] = set(re.findall(r":([a-z_0-9]+)", match.group(2)))
for match in re.finditer(r"@([a-z_]+)\s+@([a-z_]+)\s*\+\+\s*\[([^\]]*)\]", hand_src, re.S):
    attrs[match.group(1)] = attrs.get(match.group(2), set()) | set(
        re.findall(r":([a-z_0-9]+)", match.group(3))
    )

# What each generated serializer emits — the contract's field set for that message.
gen_fields = {}
for match in re.finditer(r"\n  def ([a-z_]+)\(struct\) do\n    %\{(.*?)\n    \}", gen_src, re.S):
    gen_fields[match.group(1)] = set(re.findall(r"^\s+([a-z_0-9]+):", match.group(2), re.M))

# ⚠️ Anti-vacuity on both populations. Every comparison below is a set
# difference, which is empty when everything is correct AND when nothing was
# parsed — so a drifted regex would report a clean pass over nothing. These are
# the two numbers that make the result mean anything.
if len(gen_fields) < 5:
    print(
        f"FAIL: parsed only {len(gen_fields)} generated serializer(s) from {GEN_PATH}.",
        file=sys.stderr,
    )
    print(
        "That file defines one per persisted proto message, so a number this low means the\n"
        "parse stopped matching its shape rather than that the messages are gone.",
        file=sys.stderr,
    )
    raise SystemExit(1)

omissions = set()
narrowing = 0
for match in re.finditer(r"\n  def ([a-z_]+)\(([^)]*)\) do\n(.*?)\n  end\n", hand_src, re.S):
    name, body = match.group(1), match.group(3)
    gen_call = re.search(r"Gen\.([a-z_]+)\(", body)
    if not gen_call or gen_call.group(1) not in gen_fields:
        continue
    narrowing += 1
    carried = set(re.findall(r":([a-z_0-9]+)", body))
    for attr in re.findall(r"@([a-z_]+)", body):
        carried |= attrs.get(attr, set())
    for field in gen_fields[gen_call.group(1)] - carried:
        omissions.add(f"{name}:{field}")

if narrowing < 5:
    print(
        f"FAIL: found only {narrowing} hand-written serializer(s) narrowing a Gen call "
        f"in {HAND_PATH}.",
        file=sys.stderr,
    )
    print(
        "This gate exists because those serializers drop fields silently; finding almost none\n"
        "means the parse is not reading them, not that they stopped narrowing.",
        file=sys.stderr,
    )
    raise SystemExit(1)

added = sorted(omissions - BASELINE)
stale = sorted(BASELINE - omissions)
failed = False

if added:
    failed = True
    print(
        f"FAIL: {len(added)} proto field(s) reach no client through their serializer:",
        file=sys.stderr,
    )
    by_serializer = collections.defaultdict(list)
    for pair in added:
        serializer, field = pair.split(":", 1)
        by_serializer[serializer].append(field)
    for serializer, fields in sorted(by_serializer.items()):
        print(f"  {serializer:<22} drops {', '.join(sorted(fields))}", file=sys.stderr)
    print(
        "\nThe generated side carries every contract field automatically; a hand-written\n"
        "allowlist does not. So a field added to the proto is emitted by codegen, dropped\n"
        "here, and reaches nothing — with no test failing, because `mix proto.sync --check`\n"
        "only compares generated files against generated files.\n\n"
        "Either carry the field in the serializer, or add the pair to BASELINE in this script\n"
        "in the same commit. The diff is the record that somebody decided.",
        file=sys.stderr,
    )

if stale:
    failed = True
    print(
        f"FAIL: {len(stale)} BASELINE entr(ies) name an omission that no longer exists:",
        file=sys.stderr,
    )
    for pair in stale:
        print(f"  {pair}", file=sys.stderr)
    print(
        "\nThe field is carried now, or the serializer is gone. Remove the entry — a baseline\n"
        "that keeps entries for nothing is how it stops describing the code.",
        file=sys.stderr,
    )

if not failed:
    print(
        f"OK: {narrowing} serializer(s) narrow {len(gen_fields)} generated shape(s); "
        f"{len(omissions)} omission(s), all pinned."
    )

raise SystemExit(1 if failed else 0)
PY
